// Récupération du GeoJSON
let geojson = msg.payload;

// Tri des points selon l'ordre
geojson.features.sort((a, b) => a.properties.order - b.properties.order);

// Extraction des coordonnées pour la ligne
let coords = geojson.features.map(f => f.geometry.coordinates);

// Construction du message pour worldmap
msg.payload = [
    // ---- Ligne du trajet ----
    {
        name: "Trajet GPS",
        geojson: {
            type: "Feature",
            properties: {
                name: "Trajet GPS"
            },
            geometry: {
                type: "LineString",
                coordinates: coords
            }
        }
    },

    // ---- Points / Waypoints ----
    ...geojson.features.map(f => ({
        name: f.properties.name,
        lat: f.geometry.coordinates[1],  // Attention : latitude = index 1
        lon: f.geometry.coordinates[0],  // longitude = index 0
        icon: "circle",
        layer: "Waypoints"
    }))
];

return msg;

// Extrait lat/lon du message ROS NavSatFix
const lat = msg.payload.latitude;
const lon = msg.payload.longitude;
const alt = msg.payload.altitude;

// Vérifie que les coords sont valides
if (lat === undefined || lon === undefined) {
    return null;
}

msg.payload = {
    name: "raspi",
    lat: msg.payload.latitude,
    lon: msg.payload.longitude,
    icon: "fa-ship",
    iconColor: "#00aaff",
    addtojsonarray: "track",
    trackpoints: true
};
return msg;

const labels = {
    0: "Manuel",
    1: "Autonome", 
    2: "Verrouillage",
    3: "Arrêt d'urgence"
};

msg.payload = {
    mode: msg.payload,
    label: labels[msg.payload]
};

return msg;

if (!msg.confirmed || msg.payload === null) return null;

const mode = msg.payload;

const pages = {
    0: "Manuel",
    1: "Autonome",
    2: "Verrouillage",
    3: "Urgence"
};

// Sortie 1 : publication ROS2
let ros_msg = {
    payload: JSON.stringify({
        op: "publish",
        topic: "/set_robot_mode",
        msg: { data: String(mode) }
    })
};

// Sortie 2 : redirection
let redirect_msg = mode !== 3 ? { payload: { tab: pages[mode] } } : null;

// Sortie 3 : reset du pop-up
let reset_msg = { payload: { reset: true } };

return [ros_msg, redirect_msg, reset_msg];

try {
    const rectangles = JSON.parse(msg.payload.data);
    msg.payload = rectangles;
    return msg;
} catch(e) {
    node.warn("Erreur parsing : " + e.message);
    return null;
}

