    return null;
}

try {
    const rectangles = JSON.parse(msg.payload.data);
    msg.payload = rectangles;
    return msg;
} catch(e) {
    node.warn("Erreur parsing : " + e.message);
    return null;
}

const mode = flow.get("robot_mode");

if (mode !== 0 && mode !== 1) return null;

const now = Date.now();
const lastRefused = flow.get("last_refused") || 0;

if (now - lastRefused < 5000) return null;

try {
    const detections = JSON.parse(msg.payload.data);
    if (!detections || detections.length === 0) return null;

    msg.payload = {
        show: true,
        nb: detections.length
    };
    return msg;
} catch(e) {
    node.warn("Erreur parsing : " + e.message);
    return null;
}

// Refus
if (!msg.confirmed || msg.payload === null) {
    flow.set("last_refused", Date.now());
    return null;
}

// Acceptation → passe en mode verrouillage
if (msg.payload === 2) {
    flow.set("last_accepted", Date.now());

    // Sortie 1 : reset pop-ups
    let reset_msg = { payload: { reset: true } };

    // Sortie 2 : publication ROS2
    let ros_msg = {
        payload: JSON.stringify({
            op: "publish",
            topic: "/set_robot_mode",
            msg: { data: "2" }
        })
    };

    // Sortie 3 : redirection dashboard
    let redirect_msg = { payload: { tab: "Verrouillage" } };

    return [ros_msg, redirect_msg, reset_msg];
}

return null;

// /inclinometre est maintenant sensor_msgs/Imu
const factor = 30; // 1 rad/s = 30° sur l'affichage

const roll = msg.payload.angular_velocity.y * factor * (180 / Math.PI);
const pitch = msg.payload.angular_velocity.x * factor * (180 / Math.PI);
const yaw = msg.payload.angular_velocity.z * factor * (180 / Math.PI);

msg.payload = { roll, pitch, yaw };

return msg;

// /boussole est maintenant sensor_msgs/Imu
const x = msg.payload.orientation.x;
const y = msg.payload.orientation.y;
const z = msg.payload.orientation.z;
const w = msg.payload.orientation.w;

// Conversion quaternion → yaw (cap) en degrés
const yaw = Math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
const heading = ((yaw * 180 / Math.PI) + 360) % 360;

msg.payload = { heading: heading };

return msg;

